CREATE TABLE IF NOT EXISTS page_showcase_assignments (id TEXT PRIMARY KEY, page TEXT NOT NULL CHECK(page IN ('home','about','properties','retail','rent-with-us','gallery','contact','tenant-services')), property_id TEXT NOT NULL REFERENCES buildings(id), media_asset_id TEXT NOT NULL REFERENCES media_assets(id), caption TEXT, order_index INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)), created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_page_showcase_page ON page_showcase_assignments(page,published,order_index);
